from pathlib import Path
import json,numpy as np
W=Path(__file__).resolve().parent;a=json.loads((W/'settle_contact_result.json').read_text());b=json.loads((W/'settle_contact_refined_result.json').read_text());x=np.load(W/'settle_contact_trajectory.npz');y=np.load(W/'settle_contact_refined_trajectory.npz');assert np.array_equal(x['t'],y['t']);pe=float(np.linalg.norm(x['x']-y['x'],axis=2).max());ve=float(np.linalg.norm(x['v']-y['v'],axis=2).max());force=max(float(np.linalg.norm(u-v)/max(np.linalg.norm(v),1e-6)) for u,v in zip(x['f'],y['f']));react=max(float(np.linalg.norm(u-v)/max(np.linalg.norm(v),1e-6)) for u,v in zip(x['reaction'],y['reaction']));passed=bool(a['settling_passed'] and b['settling_passed'] and pe<=1e-4 and ve<=.005 and force<=.05 and react<=.05 and a['max_linear_true_residual']<=1e-9 and b['max_linear_true_residual']<=1e-9);out={'scope':'Corrected-law intact1s finite-board hold and half-step check only; not new cut assembly','position_max_error_m':pe,'velocity_max_error_m_s':ve,'material_force_max_relative_or_floor_error':force,'support_reaction_max_relative_or_floor_error':react,'coarse_late_speed_m_s':a['late_maximum_speed_m_s'],'refined_late_speed_m_s':b['late_maximum_speed_m_s'],'both_complete_and_settled':a['settling_passed'] and b['settling_passed'],'passed':passed};(W/'settling_qualification.json').write_text(json.dumps(out,indent=2));print(json.dumps(out,indent=2));assert passed
